SELECT customers.segment, SUM(CASE WHEN orders.status = 'RETURNED' THEN orders.discount ELSE 0 END) AS returned_discount, SUM(orders.amount) AS total_amount FROM orders INNER JOIN stores ON orders.store_id = stores.id LEFT JOIN customers ON orders.customer_id = customers.id GROUP BY customers.segment HAVING SUM(orders.amount) > 9500 ORDER BY total_amount, customers.segment LIMIT 1;
